import re
from dataclasses import dataclass
from datetime import timedelta
from pathlib import Path

from logkeep import streams
from logkeep.errors import DataError

_SIZE = re.compile(r"([0-9]+)([KMGkmg]?)\Z")
_DURATION = re.compile(r"([0-9]+)([mhd])\Z")
_OFFSET = re.compile(r"([+-])([0-9]{2}):([0-9]{2})\Z")
_COUNT = re.compile(r"[0-9]+\Z")
_STREAM = re.compile(r"\[stream ([^\]]*)\]\Z")

_UNITS = {"": 1, "k": 1024, "m": 1024 * 1024, "g": 1024 * 1024 * 1024}
_SPAN = {"m": timedelta(minutes=1), "h": timedelta(hours=1), "d": timedelta(days=1)}


@dataclass(frozen=True)
class Settings:
    max_size: int | None = None
    max_age: timedelta | None = None
    naming: str = "numbered"
    offset: timedelta = timedelta(0)
    compress_after: int = 1
    keep: int = 5
    keep_days: int | None = None


def _bad(message: str):
    return DataError("policy", f"policy.ini: {message}")


def _size(v):
    if v == "off":
        return None
    m = _SIZE.match(v)
    if not m:
        raise ValueError(v)
    return int(m.group(1)) * _UNITS[m.group(2).lower()]


def _duration(v):
    if v == "off":
        return None
    m = _DURATION.match(v)
    if not m:
        raise ValueError(v)
    return int(m.group(1)) * _SPAN[m.group(2)]


def _naming(v):
    if v not in ("numbered", "dated"):
        raise ValueError(v)
    return v


def _offset(v):
    m = _OFFSET.match(v)
    if not m or int(m.group(2)) > 23 or int(m.group(3)) > 59:
        raise ValueError(v)
    delta = timedelta(hours=int(m.group(2)), minutes=int(m.group(3)))
    return -delta if m.group(1) == "-" else delta


def _count(minimum):
    def parse(v):
        if not _COUNT.match(v) or int(v) < minimum:
            raise ValueError(v)
        return int(v)

    return parse


def _keep_days(v):
    return None if v == "off" else _count(1)(v)


_KEYS = {
    "max_size": _size,
    "max_age": _duration,
    "naming": _naming,
    "offset": _offset,
    "compress_after": _count(0),
    "keep": _count(1),
    "keep_days": _keep_days,
}


class Policy:
    def __init__(self, defaults: dict, sections: dict):
        self.defaults = defaults
        self.sections = sections

    def streams(self) -> set:
        return set(self.sections)

    def settings(self, name: str) -> Settings:
        values = dict(self.defaults)
        values.update(self.sections.get(name, {}))
        return Settings(**values)


def load(path: Path) -> Policy:
    if not path.exists():
        return Policy({}, {})
    try:
        text = path.read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError) as e:
        raise _bad(str(e)) from None
    defaults: dict = {}
    sections: dict = {}
    seen_defaults = False
    current = None
    for number, raw in enumerate(text.split("\n"), 1):
        line = raw.strip()
        if not line or line[0] in "#;":
            continue
        if line[0] == "[":
            if line == "[defaults]":
                if seen_defaults:
                    raise _bad(f"line {number}: section given twice")
                seen_defaults = True
                current = defaults
                continue
            m = _STREAM.match(line)
            if not m or not streams.valid(m.group(1)):
                raise _bad(f"line {number}: unknown section")
            if m.group(1) in sections:
                raise _bad(f"line {number}: section given twice")
            current = sections[m.group(1)] = {}
            continue
        key, sep, value = line.partition("=")
        key, value = key.strip(), value.strip()
        if current is None or not sep or key not in _KEYS:
            raise _bad(f"line {number}: not a setting")
        if key in current:
            raise _bad(f"line {number}: key given twice")
        try:
            current[key] = _KEYS[key](value)
        except ValueError:
            raise _bad(f"line {number}: bad value for {key}") from None
    return Policy(defaults, sections)
